import {makePrimitives,outlineBounds} from './geometry.js';
export const SHAPES=['dots','squares','rounded','diamond','triangle','ring','ribbon','capsule','bevel','organic'];
export const metrics=s=>s.metrics||{baseline:s.rows,ascent:s.rows+1,descent:2,capHeight:s.rows,xHeight:s.rows*.7};
export const glyphStyle=(s,c)=>({...s,...s.overrides?.[c]});
export const advance=(s,c)=>(s.overrides?.[c]?.advance??(c===' '?s.columns*.6:s.columns+s.spacing));
export const inkOffset=(s,c)=>s.overrides?.[c]?.offsetX??0;
export const kern=(s,a,b)=>s.kerning?.[a+b]||0;
export function cellsFor(s,c){const cells=new Set(s.glyphs[c]||[]);for(const use of s.links?.[c]||[]){for(const [x,y]of s.components?.[use.name]?.points||[]){const xx=Math.round(x+use.x),yy=Math.round(y+use.y);if(xx>=0&&xx<s.columns&&yy>=0&&yy<s.rows)cells.add(yy*s.columns+xx)}}const rule=s.overrides?.[c]?.rule??s.rule??'none';for(const i of [...cells]){const x=i%s.columns,y=Math.floor(i/s.columns);if(rule==='mirrorX')cells.add(y*s.columns+s.columns-1-x);if(rule==='mirrorY')cells.add((s.rows-1-y)*s.columns+x)}return [...cells];}
export function validateTypography(s){
 const finite=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;for(const k of ['roundness','separation'])if(s[k]!==undefined&&!finite(s[k],0,100))throw Error('Forma inválida');
 if(s.metrics){const m=s.metrics;if(!finite(m.baseline,0,s.rows)||!finite(m.ascent,1,40)||!finite(m.descent,0,20)||!finite(m.capHeight,.5,m.ascent)||!finite(m.xHeight,.5,m.capHeight))throw Error('Métricas inválidas: x-height ≤ cap height ≤ ascender');}
 if(s.rule&&!['none','mirrorX','mirrorY'].includes(s.rule))throw Error('Regla inválida');
 for(const o of Object.values(s.overrides||{})){if(o.offsetX!==undefined&&!finite(o.offsetX,-40,40))throw Error('Margen inválido');if(o.width!==undefined&&!finite(o.width,25,200))throw Error('Ancho inválido');if(o.rule&&!['none','mirrorX','mirrorY'].includes(o.rule))throw Error('Regla local inválida');}
 if(Object.keys(s.kerning||{}).length>10000)throw Error('Demasiados pares');for(const [pair,v]of Object.entries(s.kerning||{}))if([...pair].length!==2||!finite(v,-10,10))throw Error('Kerning inválido');
 if(Object.keys(s.components||{}).length>100)throw Error('Demasiados componentes');for(const [name,c]of Object.entries(s.components||{}))if(!/^[a-zA-Z0-9 _-]{1,40}$/.test(name)||!Array.isArray(c.points)||c.points.length>400||!c.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(v=>Number.isInteger(v)&&v>=0&&v<20)))throw Error('Componente inválido');
 for(const [c,links]of Object.entries(s.links||{})){if([...c].length!==1||!Array.isArray(links)||links.length>20)throw Error('Vínculos inválidos');for(const l of links)if(!Object.hasOwn(s.components||{},l.name)||!Number.isInteger(l.x)||!Number.isInteger(l.y)||!finite(l.x,-20,20)||!finite(l.y,-20,20))throw Error('Vínculo inválido');}
}
export function audit(s){const errors=[],warnings=[],m=metrics(s);try{validateTypography(s)}catch(e){errors.push(e.message)}const chars=Object.keys(s.glyphs).filter(c=>cellsFor(s,c).length);if(!chars.length)errors.push('Dibujá al menos una letra.');const missing=[...'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyzÁÉÍÓÚÜÑáéíóúüñ0123456789'].filter(c=>!cellsFor(s,c).length);if(missing.length)warnings.push('Sin dibujo: '+missing.join(' '));for(const c of chars){const o=glyphStyle(s,c),points=cellsFor(s,c),w=(o.width??100)/100,minY=Math.min(...points.map(i=>Math.floor(i/s.columns))),maxY=Math.max(...points.map(i=>Math.floor(i/s.columns)))+1,maxX=(Math.max(...points.map(i=>i%s.columns))+.5+o.weight/200)*w+inkOffset(s,c);if(maxX>advance(s,c))warnings.push(c+': excede su ancho de avance.');if(m.baseline-minY>m.ascent||maxY-m.baseline>m.descent)warnings.push(c+': excede ascender/descender.');}for(const [pair,value]of Object.entries(s.kerning||{})){if(!chars.includes(pair[0])||!chars.includes(pair[1]))warnings.push(pair+': par con letra vacía.');if(advance(s,pair[0])+value<=0)errors.push(pair+': avance negativo.');}return {errors,warnings,characters:chars.length};}
export function generateAccents(s,replace=false){let count=0;for(const [target,base,mark]of [...'ÁÉÍÓÚáéíóú'].map((c,i)=>[c,'AEIOUaeiou'[i],'acute']).concat([['Ñ','N','tilde'],['ñ','n','tilde'],['Ü','U','dots'],['ü','u','dots']])){if(!cellsFor(s,base).length||(!replace&&cellsFor(s,target).length))continue;const source=cellsFor(s,base),top=Math.min(...source.map(i=>Math.floor(i/s.columns))),baseCells=source.map(i=>{const x=i%s.columns,y=Math.floor(i/s.columns);return Math.min(s.rows-1,Math.round(2+(y-top)*(s.rows-3)/Math.max(1,s.rows-1-top)))*s.columns+x});const mid=Math.floor(s.columns/2),marks=mark==='acute'?[mid+1, s.columns+mid]:mark==='dots'?[Math.max(0,mid-1),Math.min(s.columns-1,mid+1)]:[mid-1,s.columns+mid,mid+1];s.glyphs[target]=[...new Set([...baseCells,...marks])];if(s.links)delete s.links[target];count++;}return count;}
// Optical approximation in grid units. Keeps drawings intact and is undoable.
export function autoFit(s){
 const chars=Object.keys(s.glyphs).filter(c=>cellsFor(s,c).length),profiles={};if(!chars.length)throw Error('Dibujá o cargá algunas letras primero.');
 for(const c of chars){const o=glyphStyle(s,c),scale=(o.width??100)/100,geometry=makePrimitives(cellsFor(s,c),s.columns,o),rows=[];let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;for(let y=-1;y<=s.rows+1;y+=.0625){const [a,b]=outlineBounds(geometry,y);rows.push([a*scale,b*scale]);if(Number.isFinite(a)){minX=Math.min(minX,a*scale);maxX=Math.max(maxX,b*scale);minY=Math.min(minY,y-.03125);maxY=Math.max(maxY,y+.03125)}}profiles[c]={rows,minX,maxX,minY,maxY};}
 s.overrides??={};const gap=.65;for(const c of chars){s.overrides[c]??={};s.overrides[c].offsetX=gap/2-profiles[c].minX;s.overrides[c].advance=Math.max(1,Math.min(44,profiles[c].maxX-profiles[c].minX+gap));}
 const median=values=>{const sorted=values.slice().sort((a,b)=>a-b);return sorted[Math.floor(sorted.length/2)]},cap=chars.filter(c=>/^[A-Z]$/.test(c)),reference=cap.length?cap:chars,baseline=Math.max(0,Math.min(s.rows,median(reference.map(c=>profiles[c].maxY))));const top=Math.min(...chars.map(c=>profiles[c].minY)),bottom=Math.max(...chars.map(c=>profiles[c].maxY)),capHeight=Math.max(.5,baseline-median(reference.map(c=>profiles[c].minY))),lower=chars.filter(c=>'acemnorsuvwxz'.includes(c)),xHeight=Math.min(capHeight,Math.max(.5,lower.length?baseline-median(lower.map(c=>profiles[c].minY)):capHeight*.7));
 s.metrics={baseline,ascent:Math.max(capHeight,baseline-top)+.5,descent:Math.max(.5,bottom-baseline+.5),capHeight,xHeight};
 const pairs=[];for(const a of chars)for(const b of chars){let space=Infinity;for(let i=0;i<profiles[a].rows.length;i++){const right=profiles[a].rows[i][1],left=profiles[b].rows[i][0];if(Number.isFinite(right)&&Number.isFinite(left))space=Math.min(space,advance(s,a)+left+inkOffset(s,b)-right-inkOffset(s,a))}if(!Number.isFinite(space))continue;const adjustment=Math.round(Math.max(-Math.min(2,advance(s,a)-.5),Math.min(1,gap-space))*20)/20;if(Math.abs(adjustment)>=.05)pairs.push([a+b,adjustment]);}
 pairs.sort((a,b)=>Math.abs(b[1])-Math.abs(a[1]));s.kerning=Object.fromEntries(pairs.slice(0,10000));validateTypography(s);return {characters:chars.length,pairs:Object.keys(s.kerning).length};
}
